import difflib

def show_diff(old: str, new: str, filename: str):
    """แสดง diff สีเขียว/แดง"""
    diff = difflib.unified_diff(
        old.splitlines(),
        new.splitlines(),
        fromfile=f"a/{filename}",
        tofile=f"b/{filename}",
        lineterm="",
    )
    for line in diff:
        if line.startswith("+"):
            print(f"{C.OK}{line}{C.RESET}")
        elif line.startswith("-"):
            print(f"{C.ERR}{line}{C.RESET}")
        elif line.startswith("@@"):
            print(f"{C.INFO}{line}{C.RESET}")
        else:
            print(line)

